structlogger = structlog.get_logger()


def _imported_mcp_server(
    mcp_runtime: Optional["MCPRuntime"],
    skill_id: str,
    tool_name: str,
) -> Optional[str]:
    """Return the imported MCP server for *tool_name*, if any."""
    if mcp_runtime is None or not mcp_runtime.has_mcp_tool(skill_id, tool_name):
        return None
    return mcp_runtime.server_id_for(skill_id, tool_name)


MemoryValuesFunc = Callable[["TrackerHandle"], Mapping[str, Any]]
ResolveActivationTarget = Callable[[str], Optional["ResolvedActivationTarget"]]
AdvanceOrCompleteFunc = Callable[
    [
        str | list[NextBranch] | None,
        "UserFlowStackFrame | OrderedBlockStackFrame | SkillStackFrame",
        "TrackerHandle",
    ],
    None,
]
ConfirmedCancelFunc = Callable[["TrackerHandle"], bool]


def _awaiting_confirmation_tool_result(
    tool_name: str, confirmation_ask: Optional[str]
) -> str:
    """Build the JSON tool-result written when a call is paused for confirmation."""
    message = confirmation_ask or (
        f"Ask the user to confirm before running tool '{tool_name}'."
    )
    return json.dumps(
        {
            "status": "awaiting_confirmation",
            "message": message,
        }
    )


def _declined_confirmation_tool_result(tool_name: str) -> str:
    """Build the JSON tool-result when the user declines confirmation.

    Expected gate outcome (not a dispatch failure), so uses ``status`` like the
    pause payload rather than ``error``.
    """
    if tool_name == TOOL_CANCEL:
        # "the call was cancelled" would tell the model the skill was dropped.
        message = (
            f"User declined confirmation for tool '{tool_name}'; "
            "the skill is still active and cancel did not run."
        )
    else:
        message = (
            f"User declined confirmation for tool '{tool_name}'; "
            "the call was cancelled."
        )
    return json.dumps({"status": "declined", "message": message})


def _pending_tool_must_use_resolve_error(tool_name: str) -> str:
    """Build the JSON error when a gated tool is re-called while confirmation waits."""
    return format_error_as_json(
        f"Tool '{tool_name}' is awaiting confirmation; call "
        "resolve_tool_confirmation with confirmed=true or confirmed=false."
    )


def _resolved_tool_must_not_be_recalled_error(tool_name: str) -> str:
    """Build the JSON error when a resolved tool is re-called in the same turn."""
    return format_error_as_json(
        f"Confirmation for tool '{tool_name}' was already resolved this turn; "
        "do not re-call the tool or ask for confirmation again."
    )


class ToolConfirmationGate:
    """Pause builder tools on ``requires_confirmation`` and resume after LLM resolve.

    Internal to :class:`ToolConstraintsExecutor` — not a SkillExecutor collaborator.
    """

    def __init__(
        self,
        tool_funcs: Mapping[str, Mapping[str, Callable[..., Any]]],
        tool_invoker: ToolInvoker,
        resolve_utterance: ResolveUtteranceFunc,
        mcp_runtime: Optional["MCPRuntime"] = None,
        on_confirmed_cancel: Optional[ConfirmedCancelFunc] = None,
    ) -> None:
        self._tool_funcs = tool_funcs
        self._tool_invoker = tool_invoker
        self._resolve_utterance = resolve_utterance
        self._mcp_runtime = mcp_runtime
        self._on_confirmed_cancel = on_confirmed_cancel
        self._confirmation_ask_this_turn: Optional[AgentResponse] = None
        self._confirmation_denial_this_turn: Optional[AgentResponse] = None
        # Set when a tool is paused this turn; cleared on begin_user_turn.
        # Blocks same-turn resolve so the original request cannot approve.
        self._confirmation_paused_this_turn: bool = False
        self._resolved_tools_this_turn: set[tuple[str, str]] = set()

    def begin_user_turn(self) -> None:
        """Reset per-turn confirmation state at the start of a user turn."""
        self._confirmation_ask_this_turn = None
        self._confirmation_denial_this_turn = None
        self._confirmation_paused_this_turn = False
        self._resolved_tools_this_turn.clear()

    def consume_confirmation_ask(self) -> Optional[AgentResponse]:
        """Return and clear a confirmation ask produced during tool dispatch."""
        confirmation_ask = self._confirmation_ask_this_turn
        self._confirmation_ask_this_turn = None
        return confirmation_ask

    def consume_confirmation_denial(self) -> Optional[AgentResponse]:
        """Return and clear a denial utter queued on ``resolve(false)``."""
        confirmation_denial = self._confirmation_denial_this_turn
        self._confirmation_denial_this_turn = None
        return confirmation_denial

    async def dispatch_resolve(
        self,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
    ) -> tuple[str, bool]:
        """Handle confirmation and report whether the pending step is resolved.

        Rejects resolve in the same user turn as the pause so an omitted ask
        cannot be approved from the original request before the user answers.
        """
        if self._confirmation_paused_this_turn:
            return (
                format_error_as_json(
                    "Cannot resolve tool confirmation in the same turn as the pause; "
                    "ask the user (if needed) and wait for their reply."
                ),
                False,
            )

        pending_tool_confirmation = (
            tracker_handle.pending_tool_confirmation_for_active_frame()
        )
        if pending_tool_confirmation is None:
            return (
                format_error_as_json(
                    "No tool confirmation is pending; nothing to resolve."
                ),
                False,
            )

        confirmed = tool_args.get("confirmed")
        if not isinstance(confirmed, bool):
            return (
                format_error_as_json(
                    "resolve_tool_confirmation requires a boolean 'confirmed' argument."
                ),
                False,
            )

        if not confirmed:
            tracker_handle.clear_pending_tool_confirmation()
            structlogger.info(
                "mantle.tool_confirmation.declined",
                tool_name=pending_tool_confirmation.tool_name,
            )
            declined = _declined_confirmation_tool_result(
                pending_tool_confirmation.tool_name
            )
            self._record_confirmation_tool_event(
                tracker_handle,
                skill_id=pending_tool_confirmation.skill_id,
                tool_name=pending_tool_confirmation.tool_name,
                arguments=dict(pending_tool_confirmation.tool_args),
                result=declined,
            )
            denial_response_name = pending_tool_confirmation.utter_on_user_denial
            if denial_response_name is not None:
                resolved_denial = self._resolve_utterance(
                    denial_response_name, tracker_handle
                )
                if not resolved_denial.text.strip():
                    structlogger.warning(
                        "mantle.tool_confirmation.empty_resolved_denial",
                        tool_name=pending_tool_confirmation.tool_name,
                        response_name=denial_response_name,
                    )
                else:
                    self._confirmation_denial_this_turn = AgentResponse(
                        text=resolved_denial.text,
                        mode=ResponseMode.WAIT,
                        rephrase=resolved_denial.rephrase,
                        response_name=denial_response_name,
                        buttons=resolved_denial.buttons,
                        button_source=resolved_denial.button_source,
                        variant_metadata=resolved_denial.variant_metadata,
                        **button_source_scope_fields(
                            resolved_denial.button_source,
                            pending_tool_confirmation.skill_id,
                            tracker_handle.memory_scope()[1],
                        ),
                    )
            self._resolved_tools_this_turn.add(
                (
                    pending_tool_confirmation.skill_id,
                    pending_tool_confirmation.tool_name,
                )
            )
            return declined, True

        structlogger.info(
            "mantle.tool_confirmation.confirmed",
            tool_name=pending_tool_confirmation.tool_name,
        )
        result, resolution_complete = await self._run_confirmed_pending_tool(
            tracker_handle, pending_tool_confirmation
        )
        if resolution_complete:
            self._resolved_tools_this_turn.add(
                (
                    pending_tool_confirmation.skill_id,
                    pending_tool_confirmation.tool_name,
                )
            )
        return result, resolution_complete

    def gate_builder_tool(
        self,
        *,
        tool_gate: GatedTool,
        tool_name: str,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
        skill_id: str,
        execute_step_id: Optional[str] = None,
    ) -> str:
        """Enforce ``requires_confirmation`` before invoking a builder tool.

        Returns a JSON tool-result when the call is paused, declined, or
        blocked. The tool itself is never invoked here — only after the LLM
        confirms via ``resolve_tool_confirmation``, which looks up the callable
        from the tool registry by the stored skill/tool names.

        While confirmation is pending, the LLM must resume via
        ``resolve_tool_confirmation`` (``confirmed=true`` runs the stored call with
        its original args; ``confirmed=false`` cancels). Re-calling the gated tool
        returns an error and leaves pending state unchanged. After a completed
        resolve, an LLM re-call of the same tool in this turn is rejected; a later
        ordered ``execute_tool`` step of that tool can still pause for a new
        confirmation. A different tool name — including a digressed skill's gated
        tool while another frame still holds pending confirmation — is rejected so
        ``set_pending_tool_confirmation`` cannot overwrite the stored call. The
        resolve path records an additional ``ToolExecuted`` tagged as
        confirmation-resumed.

        Args:
            tool_gate: The gated-tool definition with ``requires_confirmation``.
            tool_name: Name of the builder tool being paused.
            tool_args: Arguments captured for the eventual confirmed call.
            tracker_handle: Active conversation handle for pending state.
            skill_id: Skill that owns the tool in the registry.
            execute_step_id: When the pause originates from an ordered-block
                ``execute_tool`` step, the step id to advance after resolve.

        Returns:
            A JSON tool-result string for the LLM (awaiting confirmation, or an
            error when the call cannot be paused).
        """
        rejection = self.rejection_for_new_pause(
            tool_name=tool_name,
            skill_id=skill_id,
            tracker_handle=tracker_handle,
            execute_step_id=execute_step_id,
        )
        if rejection is not None:
            return rejection

        validation_error = self._tool_invoker.validate_builder_tool_arguments(
            skill_id,
            tool_name,
            self._tool_funcs.get(skill_id, {}).get(tool_name),
            tool_args,
        )
        if validation_error is not None:
            return validation_error

        return self._pause_for_tool_confirmation(
            confirmation=tool_gate.requires_confirmation,
            tool_name=tool_name,
            tool_args=tool_args,
            tracker_handle=tracker_handle,
            skill_id=skill_id,
            execute_step_id=execute_step_id,
        )

    def rejection_for_new_pause(
        self,
        *,
        tool_name: str,
        skill_id: str,
        tracker_handle: TrackerHandle,
        execute_step_id: Optional[str] = None,
        replace_other_pending: bool = False,
    ) -> Optional[str]:
        """Return an error when a new pause would overwrite an open question.

        A second call of the tool that is already waiting on the active frame
        must resolve instead. Any other pending confirmation, including one
        owned by another frame, stays in place, unless *replace_other_pending*
        is set. That flag lets ``cancel`` replace it, including a cancel
        ask parked on another frame. A denial or ask already queued this turn
        still blocks a new pause.
        """
        pending_for_active_frame = (
            tracker_handle.pending_tool_confirmation_for_active_frame()
        )
        if (
            pending_for_active_frame is not None
            and pending_for_active_frame.tool_name == tool_name
        ):
            structlogger.info(
                "mantle.tool_confirmation.recall_rejected",
                tool_name=tool_name,
                event_info=(
                    "Gated tool re-called while confirmation is still pending; "
                    "caller must use resolve_tool_confirmation."
                ),
            )
            return _pending_tool_must_use_resolve_error(tool_name)

        if (
            execute_step_id is None
            and (skill_id, tool_name) in self._resolved_tools_this_turn
        ):
            structlogger.info(
                "mantle.tool_confirmation.recall_after_resolve_rejected",
                tool_name=tool_name,
            )
            return _resolved_tool_must_not_be_recalled_error(tool_name)

        pending = tracker_handle.pending_tool_confirmation
        other_pending_blocks = pending is not None and not replace_other_pending
        if (
            self._confirmation_ask_this_turn is not None
            or self._confirmation_denial_this_turn is not None
            or other_pending_blocks
        ):
            return format_error_as_json(
                f"Tool '{tool_name}' cannot run: another tool "
                "confirmation is already pending."
            )
        return None

    def run_cancel_skill(
        self,
        *,
        confirmation: RequiresConfirmation,
        tracker_handle: TrackerHandle,
    ) -> str:
        """Start the ``cancel`` confirmation, replacing another tool's open question."""
        skill_id, _memory_key = tracker_handle.memory_scope()
        rejection = self.rejection_for_new_pause(
            tool_name=TOOL_CANCEL,
            skill_id=skill_id,
            tracker_handle=tracker_handle,
            replace_other_pending=True,
        )
        if rejection is not None:
            return rejection
        return self._pause_for_tool_confirmation(
            confirmation=confirmation,
            tool_name=TOOL_CANCEL,
            tool_args={},
            tracker_handle=tracker_handle,
            skill_id=skill_id,
        )

    async def _run_confirmed_pending_tool(
        self,
        tracker_handle: TrackerHandle,
        pending_tool_confirmation: PendingToolConfirmation,
    ) -> tuple[str, bool]:
        """Invoke a stored pending tool and report whether resolution completed."""
        if (
            pending_tool_confirmation.tool_name == TOOL_CANCEL
            and self._on_confirmed_cancel is not None
        ):
            cancelled = self._on_confirmed_cancel(tracker_handle)
            tracker_handle.clear_pending_tool_confirmation()
            if not cancelled:
                return (
                    format_error_as_json(
                        "User confirmed cancel, but no active skill "
                        "was left to cancel."
                    ),
                    True,
                )
            return json.dumps({"status": "cancelled"}), True

        tools_for_skill = self._tool_funcs.get(pending_tool_confirmation.skill_id, {})
        tool_func = tools_for_skill.get(pending_tool_confirmation.tool_name)
        is_mcp = bool(
            self._mcp_runtime is not None
            and self._mcp_runtime.has_mcp_tool(
                pending_tool_confirmation.skill_id,
                pending_tool_confirmation.tool_name,
            )
        )
        if tool_func is None and not is_mcp:
            tracker_handle.clear_pending_tool_confirmation()
            missing = format_error_as_json(
                f"Confirmed tool '{pending_tool_confirmation.tool_name}' "
                "is no longer registered."
            )
            self._record_confirmation_tool_event(
                tracker_handle,
                skill_id=pending_tool_confirmation.skill_id,
                tool_name=pending_tool_confirmation.tool_name,
                arguments=dict(pending_tool_confirmation.tool_args),
                result=missing,
            )
            return missing, True

        validation_error = self._tool_invoker.validate_builder_tool_arguments(
            pending_tool_confirmation.skill_id,
            pending_tool_confirmation.tool_name,
            tool_func,
            pending_tool_confirmation.tool_args,
        )
        if validation_error is not None:
            self._record_confirmation_tool_event(
                tracker_handle,
                skill_id=pending_tool_confirmation.skill_id,
                tool_name=pending_tool_confirmation.tool_name,
                arguments=dict(pending_tool_confirmation.tool_args),
                result=validation_error,
            )
            return validation_error, False

        tracker_handle.clear_pending_tool_confirmation()
        result = await self._tool_invoker.call_builder_tool(
            tool_func,
            pending_tool_confirmation.tool_name,
            dict(pending_tool_confirmation.tool_args),
            tracker_handle,
        )
        self._record_confirmation_tool_event(
            tracker_handle,
            skill_id=pending_tool_confirmation.skill_id,
            tool_name=pending_tool_confirmation.tool_name,
            arguments=dict(pending_tool_confirmation.tool_args),
            result=result,
        )
        return result, True

    def _pause_for_tool_confirmation(
        self,
        *,
        confirmation: RequiresConfirmation | None,
        tool_name: str,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
        skill_id: str,
        execute_step_id: Optional[str] = None,
    ) -> str:
        """Persist a pending tool call and queue a WAIT confirmation ask."""
        ask_response_name = (
            confirmation.utter_for_confirmation if confirmation is not None else None
        )
        denial_response_name = (
            confirmation.utter_on_user_denial if confirmation is not None else None
        )
        confirmation_ask: Optional[str] = None
        resolved_ask = None
        if ask_response_name is not None:
            resolved_ask = self._resolve_utterance(ask_response_name, tracker_handle)
            if not resolved_ask.text.strip():
                structlogger.warning(
                    "mantle.tool_confirmation.empty_resolved_ask",
                    tool_name=tool_name,
                    response_name=ask_response_name,
                )
                return format_error_as_json(
                    f"Tool '{tool_name}' requires_confirmation.utter_for_confirmation "
                    f"({ask_response_name!r}) resolved to empty text; provide a "
                    "non-empty response body or set memory values for placeholders."
                )
            confirmation_ask = resolved_ask.text

        active_frame = tracker_handle.active_frame
        pending_tool_confirmation = PendingToolConfirmation(
            tool_name=tool_name,
            tool_args=dict(tool_args),
            confirmation_ask=confirmation_ask,
            utter_on_user_denial=denial_response_name,
            skill_id=skill_id,
            frame_id=active_frame.frame_id if active_frame is not None else None,
            execute_step_id=execute_step_id,
        )
        tracker_handle.set_pending_tool_confirmation(pending_tool_confirmation)
        self._confirmation_paused_this_turn = True
        if resolved_ask is not None:
            self._confirmation_ask_this_turn = AgentResponse(
                text=resolved_ask.text,
                mode=ResponseMode.WAIT,
                rephrase=resolved_ask.rephrase,
                response_name=ask_response_name,
                buttons=resolved_ask.buttons,
                button_source=resolved_ask.button_source,
                variant_metadata=resolved_ask.variant_metadata,
                **button_source_scope_fields(
                    resolved_ask.button_source,
                    skill_id,
                    tracker_handle.memory_scope()[1],
                ),
            )
        structlogger.info(
            "mantle.tool_confirmation.paused",
            tool_name=tool_name,
            execute_step_id=execute_step_id,
        )
        return _awaiting_confirmation_tool_result(tool_name, confirmation_ask)

    def _record_confirmation_tool_event(
        self,
        tracker_handle: TrackerHandle,
        *,
        skill_id: str,
        tool_name: str,
        arguments: Dict[str, Any],
        result: str,
    ) -> None:
        """Append the tool-run event for a resumed tool dispatch."""
        is_error, error_message = error_from_tool_payload(result)
        mcp_server = _imported_mcp_server(self._mcp_runtime, skill_id, tool_name)
        metadata: Dict[str, Any] = {
            METADATA_TOOL_SOURCE: METADATA_TOOL_SOURCE_CONFIRMATION,
        }
        if mcp_server is not None:
            metadata["mcp_server"] = mcp_server
        active_skill_id, _ = tracker_handle.memory_scope()
        tracker_handle.apply_events(
            create_tool_execution_events(
                tool_name=tool_name,
                arguments=dict(arguments),
                source="mcp" if mcp_server is not None else "local",
                result=result,
                is_error=is_error,
                error_message=error_message,
                mcp_server=mcp_server,
                metadata=metadata,
                skill_id=active_skill_id or None,
            )
        )


class ExecuteStepControl(Enum):
    """Non-response control signal for an ordered-block execute step."""

    YIELD_TO_LLM = "yield_to_llm"


# ``None`` — tool ran; caller should advance the step.
# ``AgentResponse`` — WAIT ask/error; stay on the step.
# ``ExecuteStepControl.YIELD_TO_LLM`` — stay on the step; let the LLM run.
ExecuteStepOutcome = Union[AgentResponse, ExecuteStepControl, None]


class ToolConstraintsExecutor:
    """Enforce tool constraints across LLM and ordered-block dispatch."""

    def __init__(
        self,
        *,
        skill_catalog: SkillCatalog,
        tool_funcs: Mapping[str, Mapping[str, Callable[..., Any]]],
        tool_invoker: ToolInvoker,
        resolve_utterance: ResolveUtteranceFunc,
        current_memory_values: MemoryValuesFunc,
        resolve_activation_target: ResolveActivationTarget,
        advance_or_complete: AdvanceOrCompleteFunc,
        mcp_runtime: Optional["MCPRuntime"] = None,
        on_confirmed_cancel: Optional[ConfirmedCancelFunc] = None,
    ) -> None:
        self._skill_catalog = skill_catalog
        self._confirmation_gate = ToolConfirmationGate(
            tool_funcs=tool_funcs,
            tool_invoker=tool_invoker,
            resolve_utterance=resolve_utterance,
            mcp_runtime=mcp_runtime,
            on_confirmed_cancel=on_confirmed_cancel,
        )
        self._tool_invoker = tool_invoker
        self._current_memory_values = current_memory_values
        self._resolve_activation_target = resolve_activation_target
        self._advance_or_complete = advance_or_complete
        self._mcp_runtime = mcp_runtime

    def begin_user_turn(self) -> None:
        """Reset per-turn confirmation responses."""
        self._confirmation_gate.begin_user_turn()

    def consume_confirmation_ask(self) -> Optional[AgentResponse]:
        """Return and clear a confirmation ask produced during tool dispatch."""
        return self._confirmation_gate.consume_confirmation_ask()

    def consume_confirmation_denial(self) -> Optional[AgentResponse]:
        """Return and clear a denial utter queued on confirmation decline."""
        return self._confirmation_gate.consume_confirmation_denial()

    def run_cancel_skill(
        self,
        *,
        confirmation: RequiresConfirmation,
        tracker_handle: TrackerHandle,
    ) -> str:
        """Start the ``cancel`` confirmation before the skill is dropped."""
        return self._confirmation_gate.run_cancel_skill(
            confirmation=confirmation,
            tracker_handle=tracker_handle,
        )

    async def dispatch_builder_tool(
        self,
        *,
        tool_name: str,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
        memory_values: Mapping[str, Any],
        active_skill_id: str,
        active_target_id: str,
        tool_func: Optional[Callable[..., Any]],
    ) -> str:
        """Enforce constraints and invoke an LLM-dispatched builder tool."""
        gated_tools = self._skill_catalog.resolve_tool_gates(
            active_skill_id, active_target_id
        )
        tool_gate = next((tool for tool in gated_tools if tool.name == tool_name), None)
        if tool_gate is not None and not self._is_tool_gate_open(
            tool_gate, memory_values
        ):
            structlogger.warning(
                "mantle.skill_executor.dispatch.gated_tool.blocked",
                tool_name=tool_name,
            )
            return format_error_as_json(
                f"Tool '{tool_name}' gating condition not met "
                "for the current skill state."
            )
        if tool_gate is not None and is_confirmation_gate_active(
            tool_gate.requires_confirmation
        ):
            return self._confirmation_gate.gate_builder_tool(
                tool_gate=tool_gate,
                tool_name=tool_name,
                tool_args=tool_args,
                tracker_handle=tracker_handle,
                skill_id=active_skill_id,
            )
        validation_error = self._tool_invoker.validate_builder_tool_arguments(
            active_skill_id,
            tool_name,
            tool_func,
            tool_args,
        )
        if validation_error is not None:
            return validation_error
        return await self._tool_invoker.call_builder_tool(
            tool_func, tool_name, tool_args, tracker_handle
        )

    async def dispatch_execute_step(
        self,
        *,
        step: ExecuteStep,
        tracker_handle: TrackerHandle,
        active_skill_id: str,
        tool_func: Optional[Callable[..., Any]],
    ) -> ExecuteStepOutcome:
        """Run an execute-step tool, or return a pause/block outcome when gated.

        Returns ``None`` when the tool ran successfully and the caller should
        advance the step. A closed ``requires`` gate returns
        :attr:`ExecuteStepControl.YIELD_TO_LLM`. Confirmation handling returns
        that same control signal or a WAIT :class:`AgentResponse`.
        """
        # Resolve any ``session.<namespace>.<entry>`` parameter references
        # against current memory so the tool receives the stored value
        # (e.g. the resolved card id) rather than the literal reference
        # string. Literal parameter values pass through unchanged.
        resolved_parameters = resolve_parameter_map(
            step.parameters, self._current_memory_values(tracker_handle)
        )
        memory_values = self._current_memory_values(tracker_handle)
        tool_gate = self._tool_gate(
            active_skill_id=active_skill_id,
            flow_id=tracker_handle.active_flow_id or "",
            tool_name=step.execute_tool,
        )
        if tool_gate is not None and not self._is_tool_gate_open(
            tool_gate, memory_values
        ):
            structlogger.warning(
                "mantle.skill_executor.advance_steps.gated_tool.blocked",
                tool=step.execute_tool,
            )
            # Fail closed without a user-visible error: stay on this step and
            # yield to the LLM so it can collect missing memory (or cancel).
            # LLM tool dispatch keeps the same message as tool JSON only.
            return ExecuteStepControl.YIELD_TO_LLM

        validation_error = self._tool_invoker.validate_builder_tool_arguments(
            active_skill_id,
            step.execute_tool,
            tool_func,
            resolved_parameters,
        )
        if validation_error is not None:
            structlogger.warning(
                "mantle.skill_executor.advance_steps.tool_arguments_invalid",
                tool=step.execute_tool,
            )
            return ExecuteStepControl.YIELD_TO_LLM

        confirmation_outcome = self._confirmation_outcome(
            step=step,
            tool_gate=tool_gate,
            resolved_parameters=resolved_parameters,
            tracker_handle=tracker_handle,
            active_skill_id=active_skill_id,
        )
        if confirmation_outcome is not None:
            return confirmation_outcome

        tool_result = await self._tool_invoker.call_builder_tool(
            tool_func,
            step.execute_tool,
            resolved_parameters,
            tracker_handle,
        )
        structlogger.debug(
            "mantle.skill_executor.advance_steps.execute_tool",
            tool=step.execute_tool,
            result=tool_result,
        )
        self._record_execute_tool_event(
            tracker_handle,
            tool_name=step.execute_tool,
            arguments=resolved_parameters,
            result=tool_result,
            mcp_server=_imported_mcp_server(
                self._mcp_runtime, active_skill_id, step.execute_tool
            ),
        )
        return None

    async def resolve_and_advance(
        self,
        tool_args: Dict[str, Any],
        tracker_handle: TrackerHandle,
    ) -> str:
        """Resume or cancel a pending tool, then advance an execute-step pause."""
        pending_before = tracker_handle.pending_tool_confirmation_for_active_frame()
        result, resolution_complete = await self._confirmation_gate.dispatch_resolve(
            tool_args, tracker_handle
        )
        # Ordered-block execute pauses leave the frame on the execute step;
        # advance only after a successful confirm/decline (pending cleared).
        # Invalid resolve (e.g. non-boolean ``confirmed``) leaves pending intact
        # — do not advance, or the gate would no longer cover that step.
        # Schema-invalid stored args leave pending in place so confirmation
        # still covers the step; a completed run or decline advances.
        if (
            pending_before is not None
            and pending_before.execute_step_id is not None
            and resolution_complete
        ):
            self.advance_after_confirmation(tracker_handle, pending_before)
        if (
            pending_before is not None
            and resolution_complete
            and pending_before.deferred_next
        ):
            self._requeue_deferred_instructions(pending_before)
        return result

    def _requeue_deferred_instructions(
        self, pending_tool_confirmation: PendingToolConfirmation
    ) -> None:
        """Re-queue ``ToolResult.next`` instructions held back by the pause.

        Confirm and decline both release them: they came from other tools in
        the paused response that ran successfully, so they do not depend on
        the confirmed tool's outcome. The orchestrator's batch flush runs them.
        """
        self._tool_invoker.requeue_instructions(
            [
                PendingInstruction(
                    tool_name=deferred.tool_name, instruction=deferred.instruction
                )
                for deferred in pending_tool_confirmation.deferred_next
            ]
        )
        structlogger.info(
            "mantle.skill_executor.tool.next.requeued_after_confirmation",
            pending_tool=pending_tool_confirmation.tool_name,
            count=len(pending_tool_confirmation.deferred_next),
        )

    def advance_after_confirmation(
        self,
        tracker_handle: TrackerHandle,
        pending_tool_confirmation: PendingToolConfirmation,
    ) -> None:
        """Advance past an ordered-block execute step that paused for confirmation.

        Confirm and decline both leave the tool's side effects decided (ran or
        skipped), so the block must not re-enter the same ``requires_confirmation``
        gate on the next ``advance_steps`` pass.
        """
        execute_step_id = pending_tool_confirmation.execute_step_id
        if execute_step_id is None:
            return

        frame = tracker_handle.active_frame
        if frame is None:
            return
        if (
            pending_tool_confirmation.frame_id is not None
            and frame.frame_id != pending_tool_confirmation.frame_id
        ):
            return

        flow_id = tracker_handle.active_flow_id
        step_id = tracker_handle.active_step_id
        if flow_id is None or step_id is None:
            return
        target = self._resolve_activation_target(flow_id)
        if target is None:
            return
        step = target.step_by_id(step_id)
        if not isinstance(step, ExecuteStep):
            return
        if step.id != execute_step_id:
            return
        if step.execute_tool != pending_tool_confirmation.tool_name:
            return
        if not isinstance(frame, (UserFlowStackFrame, OrderedBlockStackFrame)):
            return

        structlogger.info(
            "mantle.skill_executor.execute_step.advanced_after_confirmation",
            tool_name=pending_tool_confirmation.tool_name,
            execute_step_id=execute_step_id,
        )
        self._advance_or_complete(step.next, frame, tracker_handle)

    def _tool_gate(
        self,
        *,
        active_skill_id: str,
        flow_id: str,
        tool_name: str,
    ) -> Optional[GatedTool]:
        """Resolve the gate for an engine-driven ``execute_tool`` step.

        Delegates to :meth:`SkillCatalog.effective_tool_gate` so an
        ordered-block step honours skill-level ``requires`` /
        ``requires_confirmation`` even though the active sub-flow is non-routable.
        """
        return self._skill_catalog.effective_tool_gate(
            active_skill_id, flow_id, tool_name
        )

    @staticmethod
    def _is_tool_gate_open(tool: GatedTool, memory_values: Mapping[str, Any]) -> bool:
        """Return whether a tool's ``requires`` condition allows dispatch.

        Runtime dispatch fails closed: evaluation errors block the tool rather
        than silently allowing it.
        """
        if tool.requires is None:
            return True
        try:
            return bool(evaluate_expression(tool.requires, memory_values))
        except Exception:
            structlogger.warning(
                "mantle.skill_executor.dispatch.gate_eval_error",
                tool_name=tool.name,
            )
            return False

    def _confirmation_outcome(
        self,
        *,
        step: ExecuteStep,
        tool_gate: Optional[GatedTool],
        resolved_parameters: Dict[str, Any],
        tracker_handle: TrackerHandle,
        active_skill_id: str,
    ) -> Optional[ExecuteStepOutcome]:
        """Pause or yield for ``requires_confirmation`` on an execute step.

        Returns ``None`` when confirmation is not required for this tool.

        After a fresh gate call there are three outcomes:
        - Engine ask queued → WAIT :class:`AgentResponse` (stay on the step).
        - Pause succeeded but ``utter_for_confirmation`` was omitted → no ask
          is queued by design (LLM owns that response); yield
          :attr:`ExecuteStepControl.YIELD_TO_LLM` so the model can ask.
        - Gate failed (e.g. empty resolved ask, another confirmation already
          pending) → WAIT error; do not treat a missing ask as success.
        A pending ``cancel`` question yields to the model so this step
        does not replace that ask.
        """
        if tool_gate is None or not is_confirmation_gate_active(
            tool_gate.requires_confirmation
        ):
            return None

        pending = tracker_handle.pending_tool_confirmation_for_active_frame()
        if pending is not None and pending.tool_name == TOOL_CANCEL:
            return ExecuteStepControl.YIELD_TO_LLM
        if (
            pending is not None
            and pending.tool_name == step.execute_tool
            and pending.execute_step_id == step.id
        ):
            # Already paused on this step — let the LLM call resolve.
            return ExecuteStepControl.YIELD_TO_LLM

        tool_result = self._confirmation_gate.gate_builder_tool(
            tool_gate=tool_gate,
            tool_name=step.execute_tool,
            tool_args=resolved_parameters,
            tracker_handle=tracker_handle,
            skill_id=active_skill_id,
            execute_step_id=step.id,
        )
        self._record_execute_tool_event(
            tracker_handle,
            tool_name=step.execute_tool,
            arguments=resolved_parameters,
            result=tool_result,
        )
        confirmation_ask = self._confirmation_gate.consume_confirmation_ask()
        if confirmation_ask is not None:
            return confirmation_ask

        # No ask queued. If pending is set for this step, the pause succeeded
        # with an omitted ask template — yield to the LLM. Otherwise the gate
        # failed and we surface its error (missing ask is not an error by itself).
        pending_after = tracker_handle.pending_tool_confirmation_for_active_frame()
        if (
            pending_after is not None
            and pending_after.tool_name == step.execute_tool
            and pending_after.execute_step_id == step.id
        ):
            return ExecuteStepControl.YIELD_TO_LLM

        _, error_message = error_from_tool_payload(tool_result)
        return AgentResponse(
            text=error_message
            or (f"Tool '{step.execute_tool}' could not start " "confirmation."),
            mode=ResponseMode.WAIT,
        )

    @staticmethod
    def _record_execute_tool_event(
        tracker_handle: TrackerHandle,
        *,
        tool_name: str,
        arguments: Dict[str, Any],
        result: str,
        mcp_server: Optional[str] = None,
    ) -> None:
        """Append the tool-run event for a deterministic tool run.

        Omits LLM replay metadata (``tool_call_id`` / ``tool_batch_id``) so
        conversation history reconstruction does not treat these as prior-turn
        assistant tool calls. Eval tooling and the event ledger consume them
        directly from the tracker.
        """
        is_error, error_message = error_from_tool_payload(result)
        metadata: Dict[str, Any] = {
            METADATA_TOOL_SOURCE: METADATA_TOOL_SOURCE_EXECUTE_STEP,
        }
        if mcp_server is not None:
            metadata["mcp_server"] = mcp_server
        active_skill_id, _ = tracker_handle.memory_scope()
        tracker_handle.apply_events(
            create_tool_execution_events(
                tool_name=tool_name,
                arguments=dict(arguments),
                source="mcp" if mcp_server is not None else "local",
                result=result,
                is_error=is_error,
                error_message=error_message,
                mcp_server=mcp_server,
                metadata=metadata,
                skill_id=active_skill_id or None,
            )
        )
